//! Reflection over a synthetic SPIR-V module.
//!
//! The module is built in-process with `rspirv`'s builder: no game data, no
//! external tooling, and the fixture is generated by the test itself.

use rspirv::binary::Assemble;
use rspirv::dr::{Builder, Operand};
use rspirv::spirv::{
    AddressingModel, Capability, Decoration, ExecutionModel, FunctionControl, MemoryModel,
    StorageClass,
};

use starbreaker_shadercache::reflect;

fn module_with_bindings() -> Vec<u8> {
    let mut b = Builder::new();
    b.set_version(1, 0);
    b.capability(Capability::Shader);
    b.memory_model(AddressingModel::Logical, MemoryModel::GLSL450);

    let void = b.type_void();
    let f32_ty = b.type_float(32, None);
    let vec4 = b.type_vector(f32_ty, 4);

    // Uniform block: { float4 albedo, float4 gloss }
    let block = b.type_struct([vec4, vec4]);
    b.name(block, "MaterialBlock");
    b.member_name(block, 0, "albedo");
    b.member_name(block, 1, "gloss");
    b.decorate(block, Decoration::Block, []);
    b.member_decorate(block, 0, Decoration::Offset, [Operand::LiteralBit32(0)]);
    b.member_decorate(block, 1, Decoration::Offset, [Operand::LiteralBit32(16)]);

    let ptr_uniform = b.type_pointer(None, StorageClass::Uniform, block);
    let uniform_var = b.variable(ptr_uniform, None, StorageClass::Uniform, None);
    b.name(uniform_var, "PER_MATERIAL");
    b.decorate(
        uniform_var,
        Decoration::DescriptorSet,
        [Operand::LiteralBit32(1)],
    );
    b.decorate(
        uniform_var,
        Decoration::Binding,
        [Operand::LiteralBit32(35)],
    );

    // A sampled image in the object set.
    let image = b.type_image(
        f32_ty,
        rspirv::spirv::Dim::Dim2D,
        0,
        0,
        0,
        1,
        rspirv::spirv::ImageFormat::Unknown,
        None,
    );
    let ptr_image = b.type_pointer(None, StorageClass::UniformConstant, image);
    let image_var = b.variable(ptr_image, None, StorageClass::UniformConstant, None);
    b.name(image_var, "wearSmoothnessTexture");
    b.decorate(
        image_var,
        Decoration::DescriptorSet,
        [Operand::LiteralBit32(3)],
    );
    b.decorate(image_var, Decoration::Binding, [Operand::LiteralBit32(47)]);

    // A minimal entry point.
    let fn_ty = b.type_function(void, []);
    let main = b
        .begin_function(void, None, FunctionControl::NONE, fn_ty)
        .unwrap();
    b.begin_block(None).unwrap();
    b.ret().unwrap();
    b.end_function().unwrap();
    b.entry_point(ExecutionModel::Fragment, main, "main", [image_var]);

    b.module()
        .assemble()
        .into_iter()
        .flat_map(|w| w.to_le_bytes())
        .collect()
}

/// One resource per image kind, plus a sampler, all in set 1.
fn module_with_image_kinds() -> Vec<u8> {
    use rspirv::spirv::{Dim, ImageFormat};
    let mut b = Builder::new();
    b.set_version(1, 0);
    b.capability(Capability::Shader);
    b.memory_model(AddressingModel::Logical, MemoryModel::GLSL450);
    let void = b.type_void();
    let f32_ty = b.type_float(32, None);

    // (name, dim, arrayed, sampled: 1 = sampled, 2 = storage)
    let kinds = [
        ("tex2d", Dim::Dim2D, 0, 1),
        ("tex2darray", Dim::Dim2D, 1, 1),
        ("tex3d", Dim::Dim3D, 0, 1),
        ("texcube", Dim::DimCube, 0, 1),
        ("texcubearray", Dim::DimCube, 1, 1),
        ("texbuffer", Dim::DimBuffer, 0, 1),
        ("rwtex2d", Dim::Dim2D, 0, 2),
        ("rwbuffer", Dim::DimBuffer, 0, 2),
    ];
    let mut interface = Vec::new();
    for (i, (name, dim, arrayed, sampled)) in kinds.into_iter().enumerate() {
        let image = b.type_image(f32_ty, dim, 0, arrayed, 0, sampled, ImageFormat::Unknown, None);
        let ptr = b.type_pointer(None, StorageClass::UniformConstant, image);
        let var = b.variable(ptr, None, StorageClass::UniformConstant, None);
        b.name(var, name);
        b.decorate(var, Decoration::DescriptorSet, [Operand::LiteralBit32(1)]);
        b.decorate(var, Decoration::Binding, [Operand::LiteralBit32(i as u32)]);
        interface.push(var);
    }
    let sampler = b.type_sampler();
    let ptr = b.type_pointer(None, StorageClass::UniformConstant, sampler);
    let var = b.variable(ptr, None, StorageClass::UniformConstant, None);
    b.name(var, "linearSampler");
    b.decorate(var, Decoration::DescriptorSet, [Operand::LiteralBit32(1)]);
    b.decorate(var, Decoration::Binding, [Operand::LiteralBit32(20)]);
    interface.push(var);

    let fn_ty = b.type_function(void, []);
    let main = b.begin_function(void, None, FunctionControl::NONE, fn_ty).unwrap();
    b.begin_block(None).unwrap();
    b.ret().unwrap();
    b.end_function().unwrap();
    b.entry_point(ExecutionModel::Fragment, main, "main", &interface);
    b.module().assemble().into_iter().flat_map(|w| w.to_le_bytes()).collect()
}

#[test]
fn reports_each_image_dimension_and_samplers() {
    let r = reflect::reflect(&module_with_image_kinds()).expect("module parses");
    let ty = |name: &str| {
        r.bindings
            .iter()
            .find(|b| b.name == name)
            .unwrap_or_else(|| panic!("{name} missing"))
            .ty
            .clone()
    };
    assert_eq!(ty("tex2d"), "Texture2D");
    assert_eq!(ty("tex2darray"), "Texture2DArray");
    assert_eq!(ty("tex3d"), "Texture3D");
    assert_eq!(ty("texcube"), "TextureCube");
    assert_eq!(ty("texcubearray"), "TextureCubeArray");
    assert_eq!(ty("texbuffer"), "Buffer");
    assert_eq!(ty("rwtex2d"), "RWTexture2D");
    assert_eq!(ty("rwbuffer"), "RWBuffer");
    assert_eq!(ty("linearSampler"), "SamplerState");

    use starbreaker_shadercache::ResourceClass;
    assert_eq!(r.textures(ResourceClass::PerMaterial).count(), 8);
    let samplers: Vec<&str> =
        r.samplers(ResourceClass::PerMaterial).map(|b| b.name.as_str()).collect();
    assert_eq!(samplers, vec!["linearSampler"]);
}

#[test]
fn reflects_sets_bindings_and_block_members() {
    let spirv = module_with_bindings();
    let r = reflect::reflect(&spirv).expect("module parses");

    assert_eq!(r.entry_points.len(), 1);
    assert_eq!(r.entry_points[0].name, "main");
    assert_eq!(r.entry_points[0].execution_model, "Fragment");

    assert_eq!(r.sets(), vec![1, 3]);

    let material = r
        .bindings
        .iter()
        .find(|b| b.name == "PER_MATERIAL")
        .expect("uniform block present");
    assert_eq!(material.set, Some(1));
    assert_eq!(material.binding, Some(35));
    assert_eq!(material.storage_class, "Uniform");
    let names: Vec<&str> = material.members.iter().map(|m| m.name.as_str()).collect();
    assert_eq!(names, vec!["albedo", "gloss"]);
    assert_eq!(material.members[0].offset, Some(0));
    assert_eq!(material.members[1].offset, Some(16));
    assert_eq!(material.members[0].ty, "float4");
    assert_eq!(material.block_size, 32);

    let tex = r
        .bindings
        .iter()
        .find(|b| b.name == "wearSmoothnessTexture")
        .expect("texture present");
    assert_eq!(tex.set, Some(3));
    assert_eq!(tex.binding, Some(47));
    assert_eq!(tex.storage_class, "UniformConstant");
}

